function p12Fixture() {
  const fx = homeFixture();
  fx.files.push(['/etc/os-release', { owner: 'root', content: RECORDED['e-os-ubuntu'].out }]);
  return fx;
}
const p12Out = cmd => { const sh = new Shell(p12Fixture()); const r = sh.run(cmd); return r.out + r.err; };
const p12Shown = (log, cmd) => { const want = p12Out(cmd).trim(); return !!want && log.some(l => l.out.trim() === want); };
const p12Sudo = (...cmds) => cmds.flatMap(c => [c, `sudo ${c}`]);

